        'd_capacity' => 'প্রতিটি কাজে অনুমিত ঘণ্টা, যাঁরা করছেন তাঁদের মধ্যে ছড়ানো, যাতে ক্ষতি হওয়ার আগেই দেখা যায় কে অতিরিক্ত বোঝায় আছেন।',
