        's1_title' => 'শুরু হয় একটি লক্ষ্য দিয়ে',
        's1_text' => 'একটি অফিস স্থানান্তর: "আগামী ত্রৈমাসিকের শেষে ৪০ জন কর্মী Bradford থেকে কাজ করবেন।" বোর্ডের সম্মতি লাগলে একটি বিজনেস কেস বলে কেন এটি করার যোগ্য - আর এর প্রতিশ্রুত সুবিধাগুলোই আপনি শেষে মাপবেন।',
        's2_title' => 'টুকরো করে নিন',
        's2_text' => 'চারটি ধাপ: জরিপ ও ডিজাইন, নেটওয়ার্ক তৈরি, স্থানান্তরের সপ্তাহান্ত, থিতু হওয়া। মাইলস্টোন আপনার প্রতিশ্রুত তারিখ চিহ্নিত করে - নেটওয়ার্ক চালু, স্থানান্তরের দিন।',
        's3_title' => 'কাজের পরিকল্পনা করুন',
        's3_text' => 'প্রতিটি ধাপে কাজ বসে। কিছু কাজ অন্যের অপেক্ষায় থাকে - ক্যাবলিংয়ের আগে সুইচ বসানো যায় না - এবং সেই নির্ভরতাগুলো টাইমলাইনের তীরচিহ্ন আঁকে ও ক্রিটিক্যাল পাথ খুঁজে বের করে।',
        's4_title' => 'কে কী করছে',
        's4_text' => 'মানুষ যোগ করুন, ভূমিকা দিন, এবং কাজের অনুমান দিন যাতে ক্যাপাসিটি দেখায় কে চাপে আছেন। বড় প্রজেক্টে RACI বলে কে প্রতিটি ডেলিভারেবলের জন্য দায়বদ্ধ, আর স্টেকহোল্ডার ম্যাপ বলে কাকে খুশি রাখতে হবে।',
        's5_title' => 'কী থাকছে ঠিক করুন',
