        's6_title' => 'কী ভুল হতে পারে লক্ষ রাখুন',
        's6_text' => 'RAID লগে থাকে সুইচ দেরিতে আসার ঝুঁকি, ইন্টারনেট লাইন পিছিয়ে যাওয়ার ইস্যু। টলারেন্স বলে কতটা খারাপ মানে খুব খারাপ - আর পরিকল্পনা তা বললে হেলথ নিজে থেকেই হলুদ বা লাল হয়।',
        's7_title' => 'অর্থের হিসাব রাখুন',
