        's8_title' => 'গেটে সিদ্ধান্ত নিন',
        's8_text' => 'স্থানান্তরের সপ্তাহান্তের আগে গেটের চেকলিস্ট সম্পন্ন হতে হবে - ব্যবহারকারী পরীক্ষায় সই, একটি ব্যাকআউট প্ল্যান সংযুক্ত - তারপর কেউ বলেন চলুন।',
        's9_title' => 'যখন পরিকল্পনা সরাতে হয়',
        's9_text' => 'কেউ আরও দুটি মিটিং রুমে স্ক্রিন চান। একটি পরিবর্তনের অনুরোধ বলে এতে দিন ও অর্থে কত খরচ; অনুমোদন করলে নতুন বেসলাইন নেওয়া হয়, তাই পরিকল্পনা কতটা সরেছে তা সবসময় দেখা যায়।',
        's10_title' => 'মানুষকে জানান',
        's10_text' => 'প্রতি মাসে একটি হাইলাইট রিপোর্ট - চাইলে AI-র খসড়া, আপনার অনুমোদিত, স্টেকহোল্ডারদের ইমেইল করা। যিনি আটকে রেখেছেন বেল তাঁকে তাড়া দেয়, আর পোর্টফোলিও সব প্রজেক্ট পাশাপাশি দেখায়।',
        's11_title' => 'FreeITSM-এর বাকিটার সাথে জুড়ে দিন',
        's11_text' => 'নতুন সুইচের পরিবর্তন, স্থানান্তরে সৃষ্ট টিকিট, ক্যাবলিং কোম্পানির সাথে চুক্তি লিঙ্ক করুন। এই রেকর্ডগুলোর প্রতিটি প্রজেক্টকে নিজের দিক থেকেও দেখায়।',
        's12_title' => 'শেষ করুন - আর দেখুন এটি সার্থক ছিল কিনা',
        's12_text' => 'একটি ক্লোজার রিপোর্টসহ প্রজেক্ট বন্ধ করুন। সুবিধা মাপা চালিয়ে যান: কয়েক মাস পরে নেটওয়ার্ক টিকিট কি সত্যিই কমেছে? সেটাই আসল পরীক্ষা।',
