            'p1' => 'ব্যানারটি প্রজেক্টের নাম, তার লক্ষ্য (সম্পন্ন হলে কেমন দেখাবে), স্ট্যাটাস, কীভাবে চালানো হচ্ছে, কে নেতৃত্ব দিচ্ছেন, তারিখ এবং হেলথ রিং দেখায়। **সম্পাদনা** এর যেকোনো কিছু বদলায়, স্ট্যাটাসও: কোনো প্রজেক্টকে বন্ধ করলে, প্রকৃত শেষের তারিখ কেউ না দিয়ে থাকলে আজকের তারিখ বসে যায়।',
            'p2' => 'সংক্ষিপ্ত বিবরণ সংখ্যাগুলো একত্র করে, সঙ্গে **সময়ের সাথে অগ্রগতি** (একটি বার্নআপ: পরিকল্পনার প্রতিটি কাজ বনাম সম্পন্ন কাজ, দিন বা সপ্তাহ অনুযায়ী, লক্ষ্য শেষ চিহ্নিত - শুধু সেটি দেখতে একটি ফেজ বেছে নিন, অথবা কাজের বদলে আনুমানিক ঘণ্টা গুনুন), এখন কী ঘটছে, এরপর কী প্রাপ্য এবং সাম্প্রতিক পরিবর্তন। পরিকল্পনা ও টাইমলাইনের পর প্রজেক্ট যে টুল ব্যবহার করে তার প্রতিটির জন্য একটি ট্যাব আসে - ব্যক্তি, স্কোপ, RACI, RAID, গেট, বাজেট, পরিবর্তন নিয়ন্ত্রণ ও বেনিফিট, নিচে বর্ণিত - তারপর **ডকুমেন্ট** (পরিকল্পনা, ডিজাইন, সাইন-অফ চিঠি: আপলোড করা ফাইল বা যেখানে আছে সেখানকার লিঙ্ক), রিপোর্ট ও সংযোগ। সব টুল চালু থাকলে ট্যাব বার পাশে স্ক্রল করে। ইতিহাস যা কিছু বদলেছে এবং কে বদলেছে তার তালিকা দেয়।',
            'p3' => '**সময়ের সাথে অগ্রগতি**র নিচে (বার্নআপ, বা **বার্নডাউন** - একটি আদর্শ রেখার বিপরীতে শেষ পর্যন্ত কী বাকি) সংক্ষিপ্ত বিবরণে আছে **কাজের স্ট্যাটাস** (প্রতি ধাপে একটি বার: আপনার প্রতিটি কাজের স্ট্যাটাসে কতগুলো কাজ আছে, কতগুলো বিলম্বিত বা অন্য কাজের অপেক্ষায়), **ধাপ অনুযায়ী অগ্রগতি**, এবং **সময়ের সাথে প্রবাহ** - ক্রমবর্ধমান প্রবাহ ডায়াগ্রাম: প্রতিটি স্ট্যাটাসে কাজ, দিনে দিনে। যে ব্যান্ড ক্রমাগত চওড়া হচ্ছে সেখানে কাজ জমে যাচ্ছে। স্ট্যাটাস ৩.৩.০ থেকে দিনে একবার রেকর্ড করা হয়; তার আগে শুধু কাজ কখন তৈরি ও শেষ হয়েছে তা জানা যায়, ধূসর রঙে দেখানো।',
            'p4' => 'চার্টের ওপরে, সংক্ষিপ্ত বিবরণ বলে কোন বিষয়ে কারও নজর দরকার, প্রতিটি শুধু প্রযোজ্য হলে: মিস হওয়া মাইলস্টোন, তারিখ পেরোনো নির্ভরতা বা সিদ্ধান্ত, পর্যালোচনার সময় হওয়া বেনিফিট, সিদ্ধান্তের অপেক্ষায় থাকা পরিবর্তনের অনুরোধ এবং RAID লগে এসক্যালেট করা যেকোনো কিছু - প্রতিটির সাথে **সব দেখুন**। তারপর যে প্রজেক্ট প্রস্তাব করা হয়েছিল তার **প্রস্তাব** প্যানেল (অপেক্ষার সময় অনুমোদন ও প্রত্যাখ্যান), **টুলবক্স** (টুল দেখুন) এবং AI **ব্রিফিং**।',
