            'p1' => 'পরিকল্পনা ট্যাব প্রতিটি ফেজকে (বা ধাপ, বা স্প্রিন্ট) কাজের একটি লেন হিসেবে দেখায়, তার তারিখ, স্ট্যাটাস এবং কতগুলো কাজ সম্পন্ন তা সহ। যে কাজ এখনো কোনো ফেজে নেই তা নিচে থাকে।',
            'p2' => 'একটি লেনের নিচের বক্সে লিখে কাজ যোগ করুন - চাইলে কে করবে ও কবে প্রাপ্য তা বেছে নিন। কাজ সরাতে অন্য লেনে টেনে নিন, অথবা লেনের ক্রম ঠিক করতে লেনের মধ্যেই ওপর-নিচে টানুন - একটি রেখা দেখায় সেটি কোথায় পড়বে। কিবোর্ড থেকে, কাজের হ্যান্ডেলে ফোকাস করে ওপর বা নিচের অ্যারো চাপুন; ফোনে প্রতিটি কাজের সরানোর বোতামে ওপরে ও নিচে আছে। একটি কাজ কাজ বোর্ডে খুলতে তাতে ক্লিক করুন, সেখানে এটি অন্য যেকোনো কাজের মতোই সম্পাদনা করা যায়।',
            'p3' => 'একটি ফেজে কাজ শুরু হলে **শুরু** চাপুন আর শেষ হলে **সমাপ্ত** চাপুন। কাজের সারির শেষের ক্রস চিহ্নটি তাকে প্রজেক্ট থেকে সরায়; কাজটি নিজে থেকে যায়।',
            'p4' => 'মাইলস্টোন হলো প্রজেক্টের প্রতিশ্রুত তারিখ - স্থানান্তরের দিন, গো-লাইভ, বোর্ডের সাইন-অফ। একটি যোগ করতে পরিকল্পনা ট্যাবে **মাইলস্টোন** চাপুন, কোনো ফেজে বা পুরো প্রজেক্টের জন্য। প্রতিটি ফেজ তার মাইলস্টোনগুলো হীরার আকারে দেখায়; ঘটলে **অর্জিত** টিক দিন। যে মাইলস্টোনের তারিখ অর্জন ছাড়াই পেরিয়ে যায় সেটি মিস হয়েছে, এবং প্রজেক্টকে অ্যাম্বার করে দেয়।',
            'step1' => 'পোর্টফোলিওতে **নতুন** চাপুন, প্রজেক্টের একটি নাম ও লক্ষ্য দিন, এবং কীভাবে চালাবেন তা বেছে নিন।',
            'step2' => 'পরিকল্পনা ট্যাবে, কাজ যেসব ফেজে পড়ে সেগুলো যোগ করুন।',
