            'p2' => 'মাউস দিয়ে, কাজ বা ফেজ সরাতে একটি বার টানুন, অথবা কখন শুরু বা শেষ হবে তা বদলাতে যেকোনো প্রান্ত টানুন; মাইলস্টোন সরাতে একটি হীরা টানুন। প্রতিটি সরানো সঙ্গে সঙ্গে সংরক্ষিত হয় এবং হাতে সম্পাদনার মতো একই নিয়মের মধ্য দিয়ে যায়, তাই কাজ বোর্ড, ক্যালেন্ডার ও হেলথ সাথে সাথে বদলায়। এর বদলে খুলতে একটি বারে ক্লিক করুন। তারিখ ছাড়া কাজ আঁকা হয় না; ট্যাব বলে কতগুলো আছে।',
            'p3' => 'জুম করতে **দিন**, **সপ্তাহ** বা **মাস** বেছে নিন। ফোনে চার্ট পাশে স্ক্রল করে; জিনিস সরানোর জন্য সেগুলোতে ট্যাপ করে তারিখ বদলান।',
            'p4' => '**নির্ভরতা।** একটি কাজের সারির লিঙ্ক বোতামটি বলে সেটি কীসের অপেক্ষায়: অন্য একটি কাজ শেষ না হওয়া পর্যন্ত একটি কাজ শুরু হতে পারে না, ঐচ্ছিকভাবে কয়েক দিনের ফাঁক সহ। চার্টে তীর সেগুলো জোড়ে - পরিকল্পনায় সংঘাত থাকলে লাল ও ড্যাশযুক্ত (অন্যটি শেষ হওয়ার আগেই এটি শুরু হয়)। **ক্রিটিক্যাল পাথ** যেসব কাজের কোনো স্ল্যাক নেই সেগুলো বেছে নেয় - যেকোনো দিন পিছোলে শেষও পিছোয় - এবং বাকিগুলো ঝাপসা করে। লুপ গ্রহণ করা হয় না। পরিকল্পনায় কোনো কাজ যার অপেক্ষায় আছে তা অসমাপ্ত থাকলে **১টির অপেক্ষায়** দেখায়, আর তার তারিখ মিলতে না পারলে **সংঘাত**।',
