            'p1' => 'কোনো কাজকে একটি **প্রাক্কলন** দিন - কত ঘণ্টা লাগা উচিত - তার পরিকল্পনা সারির বক্সে, অথবা কাজ বোর্ডের কাজের উইন্ডোতে। প্রতিটি লেন ও সংক্ষিপ্ত বিবরণ তখন প্রাক্কলিত বনাম লগ করা সময় দেখায়, এবং প্রাক্কলনের চেয়ে বেশি সময় লগ হলে সারি লাল হয়ে যায়।',
            'p2' => 'প্রজেক্টের ওপরে থাকা **ক্যাপাসিটি** পৃষ্ঠায় প্রজেক্টের কাজ আছে এমন প্রতিজনের জন্য একটি সারি এবং প্রতি সপ্তাহের জন্য একটি কলাম আছে। একটি সপ্তাহের বোঝা হলো তাঁর বাকি প্রজেক্ট কাজ - প্রতিটি কাজের প্রাক্কলন থেকে ইতিমধ্যে লগ করা সময় বাদ দিয়ে, শুরু (বা আজ) থেকে প্রাপ্য তারিখ পর্যন্ত কর্মদিবসগুলোয় ছড়িয়ে - সাথে সার্ভিস-ডেস্ক রোটায় তাঁর শিফট, সপ্তাহে তাঁর কাজের ঘণ্টার বিপরীতে। সবুজ মানে জায়গা আছে, অ্যাম্বার মানে টানাটানি, লাল মানে অতিরিক্ত বোঝাই। এর পেছনের কাজগুলো দেখতে একটি সারি খুলুন।',
            'p3' => 'সপ্তাহগুলোর পাশে আছে প্রতিজনের কতগুলো চালু প্রজেক্টে খোলা কাজ আছে (তিন বা তার বেশি হলে চিহ্নিত), তাঁদের খোলা টিকিট, এবং প্রাপ্য তারিখ ছাড়া কাজ। প্রাক্কলন ছাড়া কাজ গোনা হয় কিন্তু যোগ করা হয় না, তাই পৃষ্ঠা বলে কতগুলো আছে - অজানা কাজ একটি ঝুঁকি, শূন্য নয়। **প্রজেক্ট - সেটিংস - হেলথ** সপ্তাহে ঘণ্টা (৩৭.৫), কখন সপ্তাহ অ্যাম্বার হয় (৮৫%), কতগুলো প্রজেক্ট মানে \'কয়েকটি\', কোন দিনগুলো কর্মদিবস, এবং রোটার শিফট গোনা হবে কি না ঠিক করে (শুধু অন-কল রোটার জন্য বন্ধ করুন)।',
        ],
        'methods' => [
            'nav' => 'কাজের পদ্ধতি',
