            'intro' => 'একটি প্রজেক্ট, দেখার তিনটি উপায়।',
            'p1' => 'আপনি একটি প্রজেক্ট কীভাবে চালান তা ঠিক করে তার টাইম বক্সগুলোর কী নাম হবে এবং সেগুলো কেমন আচরণ করবে। ভেতরে ভেতরে প্রতিটি প্রজেক্ট একই ভাবে তৈরি, যে কারণে মত বদলানো নিরাপদ।',
            'p2' => 'মাঝপথে পদ্ধতি বদলালে কিছু হারায় না। শেষ হওয়া ফেজগুলো যে নামে চলেছিল সেটি রাখে, খোলাগুলো নতুন পদ্ধতির নাম নেয়, এবং বদলটি প্রজেক্টের ইতিহাসে লেখা হয়। নতুন পদ্ধতি একসাথে শুধু একটি টাইম বক্স চলতে দিলে, সবচেয়ে আগেরটি চলমান থাকে এবং বাকিগুলো পরিকল্পিত অবস্থায় ফিরে যায়।',
            'simple_d' => 'ফেজ ও কাজ। যেকোনো সংখ্যক ফেজ একসাথে চলতে পারে।',
            'staged_d' => 'ধাপ, যা পরেরটি শুরুর আগে একটি একটি করে শেষ করেন, PRINCE2-র ধাঁচে - বোর্ডকে রিপোর্ট করা প্রজেক্টের জন্য।',
