            'intro' => 'প্রজেক্ট চালানোর প্রতিটি পদ্ধতি নিজস্ব একটি সেট চালু করে।',
            'p1' => 'একটি প্রজেক্ট আটটি টুল ব্যবহার করতে পারে, প্রতিটি নিজস্ব ট্যাবে: ব্যক্তি, স্কোপ, RACI, RAID, গেট, বাজেট, পরিবর্তন নিয়ন্ত্রণ ও বেনিফিট। কীভাবে চালানো হয় তা ঠিক করে শুরুতে কোনগুলো চালু থাকবে:',
            'p2' => 'একটি প্রজেক্ট মানানসই করতে, তা **সম্পাদনা** করে **টুল** এর অধীনে টুলগুলো টিক দিন বা টিক তুলুন (বিভাগটি সম্পাদনার সময় আসে, তৈরির সময় নয়)। একটি টুল বন্ধ করলে শুধু তার ট্যাব লুকায়: এর ভেতরের কিছুই মোছা হয় না, আর আবার চালু করলে সবকিছু ফিরে আসে। একই ডায়ালগে প্রজেক্ট কীভাবে চালানো হয় তা বদলালে টুলগুলো নতুন পদ্ধতির নিজস্ব সেটে ফিরে যায়।',
            'p3' => 'সংক্ষিপ্ত বিবরণের **টুলবক্স** সেই টুলগুলো দেখায় যা প্রজেক্ট এখনো ব্যবহার করছে না - প্রতিটি কীসের জন্য এবং কখন লাগবে - যাতে একটি সহজ প্রজেক্ট প্রয়োজনমতো তার টুল বাড়াতে পারে। প্রজেক্ট নিজে যেগুলো প্রস্তাব করে সেগুলো আগে আসে, কারণ সহ **প্রস্তাবিত** চিহ্নিত: তিন বা তার বেশি ধাপ গেটের প্রস্তাব দেয়, ইতিমধ্যে সরে যাওয়া লক্ষ্য তারিখ পরিবর্তন নিয়ন্ত্রণের প্রস্তাব দেয়, বিলম্বিত কাজ RAID-এর প্রস্তাব দেয়। **যোগ করুন** টুলটি চালু করে, ঠিক সম্পাদনার মতোই (RACI যোগ করলে ব্যক্তি ও স্কোপও যোগ হয়, কারণ ম্যাট্রিক্সটি সেগুলো থেকে তৈরি)। **লুকান** আপনার ব্রাউজারে সেই প্রজেক্টের জন্য এটি লুকায়। শুধু যাঁরা প্রজেক্ট বদলাতে পারেন তাঁরা এটি দেখেন, এবং প্রজেক্ট বন্ধ হলে নয়। **প্রজেক্ট - সেটিংস - সাধারণ - সংক্ষিপ্ত বিবরণে টুলবক্স** এটি সবার জন্য বন্ধ করে।',
