            'p2' => 'ভূমিকাগুলো আসে **প্রজেক্ট - সেটিংস - ভূমিকা** থেকে, যা PRINCE2-ধাঁচের ভূমিকা দিয়ে শুরু হয় (Executive, Senior User, Senior Supplier, Project Manager, Team Manager, Project Assurance এবং Project Support) এবং সাথে দলের সদস্য ও স্টেকহোল্ডার।',
            'p4' => '**কে দেখতে পারবে** (প্রজেক্টের ফর্মে): **প্রজেক্ট অ্যাক্সেসসহ সবাই**, অথবা **শুধু সদস্য** - কেবল তার প্রজেক্ট ম্যানেজার, যিনি এটি তৈরি করেছেন, তার সদস্যরা (সরাসরি বা দলের মাধ্যমে) এবং যাঁরা প্রজেক্ট পরিচালনা করেন। HR, নিরাপত্তা বা গোপনীয় কাজের জন্য। বাকি সবার কাছে শুধু-সদস্য প্রজেক্টের অস্তিত্বই নেই: পোর্টফোলিও, অনুসন্ধান, ব্যক্তি, Watchtower, Warbot বা API-তে নেই, এবং এর তারিখ ভাগ করা ক্যালেন্ডারের বাইরে থাকে। ক্যাপাসিটি তবু এর কাজ গোনে, "একটি শুধু-সদস্য প্রজেক্ট" হিসেবে। যাঁকে অনুমোদন বা সাইন-অফ করতে বলবেন তাঁকে এটি খুলতে সদস্য হতে হবে। নতুন প্রজেক্ট শুরু হয় প্রজেক্ট -> সেটিংস -> সাধারণ যেভাবে বলে সেভাবে।',
            'p5' => '**কার জানা দরকার?** - স্টেকহোল্ডার মানচিত্র। কোনো সদস্যের ওপর **স্থাপন** তাঁর **ক্ষমতা** (প্রজেক্টকে কতটা প্রভাবিত করতে পারেন) ও **আগ্রহ** (এটি তাঁকে কতটা প্রভাবিত করে) ১ থেকে ৫, তিনি কোথায় দাঁড়িয়ে (সমর্থক, সহায়ক, নিরপেক্ষ, সংশয়ী বা বাধাদাতা) এবং তাঁকে কীভাবে জানানো হয় তা ঠিক করে। মানচিত্র প্রত্যেককে একটি চতুর্থাংশে বসায় - ঘনিষ্ঠভাবে পরিচালনা, সন্তুষ্ট রাখা, জানিয়ে রাখা, নজরে রাখা (৩ ও তার বেশি উচ্চ গণ্য) - এবং এর নিচের **যোগাযোগ পরিকল্পনা** স্থাপিত সবাইকে তালিকাভুক্ত করে, সবচেয়ে গুরুত্বপূর্ণ আগে। বোর্ড, স্পনসর ও প্রভাবিত ব্যক্তিদের সদস্য হিসেবে যোগ করুন (ব্যক্তি মডিউলের ব্যক্তি সহ) তাঁদের স্থাপন করতে।',
