            'p1' => 'স্কোপ ট্যাব হলো প্রজেক্টের সরবরাহযোগ্য বিষয় ও প্রয়োজনের একটি বোর্ড, পাঁচটি কলামে: অবশ্যই, উচিত, হতে পারে, এবার নয় ও অগ্রাধিকার দেওয়া হয়নি। একটি কলামের নিচের বক্সে লিখে সেখানে একটি যোগ করুন, এবং অগ্রাধিকার বদলাতে একটি কার্ড অন্য কলামে টানুন - সরানোটি ইতিহাসে লেখা হয়।',
            'p2' => 'একটি কার্ড খুলতে তাতে ক্লিক করুন। শিরোনাম ও অগ্রাধিকারের পাশাপাশি এর আছে একটি স্ট্যাটাস (প্রস্তাবিত, সম্মত, চলমান, গৃহীত বা বাদ), এটি যে ফেজের অংশ, একটি বিবরণ, এবং **সম্পন্ন হবে যখন...** - কীভাবে বুঝবেন এটি সরবরাহ করা হয়েছে। একটি সরবরাহযোগ্য বিষয় মুছলে RACI ম্যাট্রিক্সে তার সারিও মুছে যায়।',
