            'intro' => 'ওপরে ব্যক্তিরা, পাশে সরবরাহযোগ্য বিষয়।',
            'p1' => 'RACI ট্যাব হলো প্রজেক্টের ব্যক্তিদের (কলাম) বনাম তার সরবরাহযোগ্য বিষয়ের (সারি) একটি গ্রিড, তাই এতে দুটোই লাগে: আগে ব্যক্তি ট্যাবে ব্যক্তি ও স্কোপ ট্যাবে সরবরাহযোগ্য বিষয় যোগ করুন। বাদ দেওয়া সরবরাহযোগ্য বিষয় বাদ থাকে।',
            'p2' => 'একটি ঘরে ক্লিক করে তাকে R, A, C, I এবং আবার খালিতে ঘোরান। প্রতিটি সরবরাহযোগ্য বিষয়ের জন্য একজন দায়বদ্ধ ব্যক্তি থাকেন: দ্বিতীয় একজনের জন্য A দিলে আগের জন Responsible হয়ে যান, কারণ তিনি তখনও কাজ করছেন। যে সারিতে কেউ দায়বদ্ধ বা কেউ দায়িত্বপ্রাপ্ত নেই তা খসড়ার সময় অনুমোদিত, এবং সরবরাহযোগ্য বিষয়ের নামের নিচে চিহ্নিত থাকে।',
        ],
        'raid' => [
            'nav' => 'RAID',
            'title' => 'RAID লগ এবং হিট ম্যাপ',
            'intro' => 'কী ভুল হতে পারে, আপনি কী ধরে নিচ্ছেন, কী ভুল হয়ে গেছে, কীসের অপেক্ষায় আছেন এবং কী সিদ্ধান্ত নিয়েছেন।',
            'p1' => 'RAID ট্যাবে ছয় ধরনের এন্ট্রি লগ করা হয়: ঝুঁকি, অনুমান, ইস্যু, নির্ভরতা, সিদ্ধান্ত এবং শিক্ষণীয় বিষয়। প্রতিটির একটি শিরোনাম, বিস্তারিত, একজন মালিক, পর্যালোচনার শেষ তারিখ এবং একটি স্ট্যাটাস থাকে, খোলা বা বন্ধ। উপরের বোতামগুলো ধরন অনুযায়ী ফিল্টার করে এবং প্রতিটির কতগুলো খোলা তা দেখায়; **বন্ধ দেখান** বন্ধ এন্ট্রিগুলো আবার তালিকায় ফিরিয়ে আনে। এন্ট্রি লগ করা, বন্ধ করা, আবার খোলা এবং মুছে ফেলা সবই ইতিহাসে লেখা হয়।',
            'p2' => 'একটি ঝুঁকির সম্ভাবনা ও প্রভাব থাকে, প্রতিটি পাঁচ ধাপের স্কেলে, এবং সম্ভাবনা গুণ প্রভাব দিয়ে একটি **স্কোর** থাকে, ১ থেকে ২৫। এর একটি প্রতিক্রিয়াও থাকতে পারে (এড়ানো, কমানো, হস্তান্তর, গ্রহণ বা ভাগ করা) এবং কীভাবে তা সামলানো হবে তার একটি পরিকল্পনা। একটি ইস্যুর প্রভাব থাকে এবং সেটি একটি টিকিটের সাথে যুক্ত করা যায়, যদি আপনি টিকিটটি খুলতে পারেন এবং তা প্রজেক্টের কোম্পানির অন্তর্ভুক্ত হয়।',
            'p3' => 'হিট ম্যাপ, **কী ভুল হতে পারে?**, সম্ভাবনা ও প্রভাব দুটোই আছে এমন প্রতিটি খোলা ঝুঁকিকে পাঁচ-বাই-পাঁচ গ্রিডে বসায়, স্কোর অনুযায়ী সবুজ থেকে লাল রঙে। শুধু সেই ঝুঁকিগুলো তালিকাভুক্ত করতে একটি ঘরে ক্লিক করুন; পরিষ্কার করতে আবার ক্লিক করুন, অথবা **সব দেখান** চাপুন। দুটি স্কেলের শব্দগুলো **প্রজেক্ট - সেটিংস - RAID** থেকে আসে।',
            'p5' => 'একটি **নির্ভরতা** হলো প্রজেক্টের বাইরে থেকে যা দরকার - বাড়িওয়ালা ফিট-আউট শেষ করা, সরবরাহকারীর ডেলিভারি, অন্য কোনো দল। এর তারিখ হলো কবে নাগাদ দরকার; এসে পৌঁছালে বন্ধ করুন। একটি **সিদ্ধান্ত** নেওয়ার আগেই লগ করা হয়, কবে নাগাদ নিতে হবে সেই তারিখসহ, এবং নেওয়া হয়ে গেলে বন্ধ করা হয়, **সিদ্ধান্ত নিয়েছেন**, **সিদ্ধান্তের তারিখ** ও **কেন** সহ (যেকোনো নাম - স্পনসর, বোর্ড)। সিদ্ধান্ত লগ হিসেবে দেখতে **সিদ্ধান্ত** বেছে নিন। তারিখ পেরিয়ে যাওয়ার পরও কোনো নির্ভরতা বা সিদ্ধান্ত খোলা থাকলে প্রজেক্ট হলুদ হয়ে যায়।',
            'p6' => 'একটি সংরক্ষিত এন্ট্রি খুলে সেটি **এসক্যালেট** করুন - যখন প্রজেক্ট ম্যানেজারের উপরে কারও দরকার হয় - কী দরকার তা বলে একটি লাইনসহ। এটি সংক্ষিপ্ত বিবরণে, RAID ট্যাবে এবং পোর্টফোলিও কার্ডে চিহ্নিত হয়ে দেখায় যতক্ষণ না তা **এসক্যালেশন প্রত্যাহার** বা বন্ধ করা হয়; প্রজেক্ট ম্যানেজারকে জানানো হয়, এবং একটি ওয়ার্কফ্লো স্পনসরকে জানাতে পারে। **অনুসরণীয় পদক্ষেপ** হলো এন্ট্রি থেকে তৈরি প্রজেক্টের কাজ - সিদ্ধান্তের পর যা ঠিক হয়েছে, ঝুঁকির প্রশমন - এবং কতগুলো সম্পন্ন হয়েছে তা লগে দেখানো হয়।',
            'p4' => 'একটি সংরক্ষিত **শিক্ষণীয় বিষয়** খুলে **নলেজ** চাপুন, এটিকে নলেজ নিবন্ধের খসড়ায় রূপ দিতে: এর বিস্তারিত নিবন্ধ হয়ে যায়, প্রজেক্টের একটি লিঙ্কসহ, এবং সংযোগ ট্যাবে এটি যুক্ত হয়। নলেজে এটি পড়ুন, তারপর প্রকাশ করুন। একটি সংরক্ষিত **ইস্যু** খুলে **তুলুন** চাপুন, ইতিমধ্যে থাকা টিকিট যুক্ত করার বদলে এটি থেকে নতুন টিকিট তুলতে: আপনি অনুরোধকারী, এটি ইস্যুর মালিকের কাছে যায় (বা আপনার কাছে), এটি প্রজেক্টের কোম্পানির অন্তর্ভুক্ত হয়, এবং ইস্যু ও প্রজেক্ট দুটোই এতে লিঙ্ক করা থাকে। প্রতিটি এন্ট্রির জন্য একবারই করা যায়, এবং প্রজেক্ট পরিবর্তনের অনুমতির পাশাপাশি নলেজ বা টিকিটে অ্যাক্সেসও লাগে।',
            'p7' => '**রপ্তানি** (বন্ধ দেখানের পাশে) পুরো লগ - সব ধরন, খোলা ও বন্ধ - Excel ওয়ার্কবুক বা CSV ফাইল হিসেবে ডাউনলোড করে, মালিক, স্কোর, প্রতিক্রিয়া, সিদ্ধান্ত ও অনুসরণীয় পদক্ষেপসহ।',
        ],
        'gates' => [
            'nav' => 'গেট',
            'title' => 'গেট, টলারেন্স এবং ব্যতিক্রম',
            'intro' => 'PRINCE2 ধাঁচে একটি ধাপভিত্তিক প্রজেক্ট যে নিয়ন্ত্রণগুলোর কাছে জবাবদিহি করে।',
            'p1' => 'গেট ট্যাবে তিনটি জিনিস থাকে। **বিজনেস কেস** বলে প্রজেক্টটি কেন করার যোগ্য - সুবিধা, খরচ ও ঝুঁকি - এবং প্রতিটি গেটে এটি পর্যালোচনার জন্য থাকে। **টলারেন্স** বলে সিদ্ধান্তের দরকার হওয়ার আগে প্রজেক্ট কতটা সরে যেতে পারে। **ধাপ গেট** প্রতিটি ধাপের শেষে একটি সিদ্ধান্ত রেকর্ড করে।',
            'p2' => 'দুটি টলারেন্স আছে, এবং একটি ফাঁকা রাখলে তা বন্ধ থাকে। কাজ এখনো খোলা থাকা অবস্থায় লক্ষ্য শেষ তারিখ বা চলমান ধাপের শেষ তারিখ ততদিনের বেশি অতীতে চলে গেলে **অনুমোদিত বিলম্বের দিন** অতিক্রান্ত হয়। RAID লগে কোনো খোলা ঝুঁকির স্কোর তার চেয়ে বেশি হলে **অনুমোদিত সর্বোচ্চ ঝুঁকির স্কোর** অতিক্রান্ত হয়।',
            'p3' => 'টলারেন্স পেরিয়ে গেলে প্রজেক্ট একটি **ব্যতিক্রম** হয়ে যায়। এটি থাকাকালীন হিসাব করা হেলথ হয় পথের বাইরে, একটি **টলারেন্স অতিক্রান্ত** ব্যানার সংক্ষিপ্ত বিবরণ ও গেট ট্যাবে প্রতিটির নাম দেখায়, এবং পোর্টফোলিওতে প্রজেক্টের কার্ডে একটি **ব্যতিক্রম** চিপ থাকে। ব্যতিক্রম প্রজেক্ট দেখানোর প্রতিবার হিসাব করা হয়, কখনো সংরক্ষিত হয় না, তাই প্রজেক্ট টলারেন্সের মধ্যে ফিরে এলে সেগুলো নিজে থেকেই মুছে যায়। এগুলো শুধু গেট টুল চালু থাকা একটি চলমান প্রজেক্টে প্রযোজ্য, এবং হাতে ঠিক করা হেলথ যেমন ছিল তেমনই থাকে।',
            'p4' => 'চলমান বা সম্পন্ন একটি ধাপে **সিদ্ধান্ত** চাপুন (পরিকল্পিত ধাপে কোনো বোতাম নেই), একটি সিদ্ধান্ত বেছে নিন এবং নোট যোগ করুন। সিদ্ধান্ত, কে নিয়েছেন এবং কখন, ধাপেই থেকে যায়, এবং তা ইতিহাসে লেখা হয়। ইতিমধ্যে সম্পন্ন একটি ধাপে রেকর্ড করা গো শুধু সিদ্ধান্তটি রেকর্ড করে: এটি আরেকটি ধাপ শুরু করে না।',
            'p5' => 'সিদ্ধান্তের আগে গেট সংযোগ ট্যাবে যুক্ত **পরিবর্তনগুলো** পরীক্ষা করে। যেগুলো এখনো খোলা এবং অনুমোদিত নয় - অনুমোদনের অপেক্ষায়, বা কেউ জমা দেয়নি এমন খসড়া - সেগুলো গেট ডায়ালগে স্ট্যাটাস ও পরিকল্পিত শুরুর তারিখসহ তালিকাভুক্ত হয়, এবং চলমান ধাপে কতগুলো তা বলা একটি চিপ থাকে। এটি সতর্কতা, বাধা নয়: সিদ্ধান্ত তবুও আপনার। আপনি এটি দেখেন শুধু যদি আপনি পরিবর্তন খুলতে পারেন।',
            'p6' => 'প্রতিটি গেটের একটি **চেকলিস্ট** থাকতে পারে, গো-এর আগে যা সত্য হতে হবে তার: টিক দেওয়ার একটি **চেক**; একটি **নথি** - প্রজেক্টের **নথি** ট্যাব থেকে একটি ফাইল বেছে সম্পন্ন করা হয় (ব্যাকআউট পরিকল্পনা, পরীক্ষার রিপোর্ট); একজন নামকরা ব্যক্তির **সাইন-অফ**, যাঁকে বেলে জানানো হয় এবং যিনিই একমাত্র সাইন করতে পারেন; অথবা একটি যুক্ত **পরিবর্তন** যা পরিবর্তনে অনুমোদিত হতে হবে। একটি গেটকে **গো-লাইভ গেট** করলে এটি একটি শুরুর চেকলিস্ট পায় - ব্যবহারকারী গ্রহণযোগ্যতা পরীক্ষা সাইন-অফ, ব্যাকআউট পরিকল্পনা, পরিবর্তন অনুমোদিত, সাপোর্ট হস্তান্তর সম্মত - রাখার, বদলানোর বা যোগ করার জন্য। প্রতিটি আইটেম সম্পন্ন না হওয়া পর্যন্ত গো প্রত্যাখ্যাত হয় (স্টপ কখনো নয়); প্রজেক্ট - সেটিংস - সাধারণ এটিকে সতর্কতায় বদলাতে পারে, তখন যা খোলা ছিল তা গেটের নোটে লেখা হয়।',
            'go_d' => 'ধাপটি বন্ধ করে এবং পরবর্তী পরিকল্পিত ধাপটি শুরু করে।',
            'go_with_conditions_d' => 'গো-এর মতোই, শর্তগুলো নোটে লেখা সহ - সেগুলো আবশ্যক।',
            'stop_d' => 'রেকর্ড করে যে প্রজেক্টটি পরিকল্পনা অনুযায়ী চালিয়ে যাওয়া উচিত নয়। এটি কোনো ধাপ বদলায় না: পরবর্তীতে কী হবে তা প্রজেক্ট যারা চালাচ্ছেন তাঁদের সিদ্ধান্ত।',
        ],
        'templates' => [
            'nav' => 'টেমপ্লেট',
            'title' => 'টেমপ্লেট থেকে শুরু করুন',
            'intro' => 'এমন একটি প্রজেক্ট যা আগে থেকেই পরিকল্পিত অবস্থায় আসে।',
            'p1' => 'প্রজেক্ট তৈরি করার সময় **থেকে শুরু করুন** টেমপ্লেট দেয়: অফিস স্থানান্তর, ল্যাপটপ রিফ্রেশ, মেইল মাইগ্রেশন, Windows 11 রোলআউট এবং সার্ভিস ডেস্ক উন্নয়ন বিল্ট-ইন আসে। একটি বেছে নিন, তাহলে প্রজেক্টটি এর ধাপ, কাজ, পরিধি, ঝুঁকি ও টলারেন্স আগে থেকেই বসানো অবস্থায় তৈরি হয়, এবং এর চালানোর পদ্ধতি, রঙ, আইকন ও লক্ষ্য আপনার জন্য পূরণ করা থাকে। ফর্মে আপনি যা লেখেন তা টেমপ্লেটের চেয়ে অগ্রাধিকার পায়।',
            'p2' => 'একটি টেমপ্লেট তার তারিখগুলো শুরু থেকে কত দিন হিসেবে রাখে, তাই প্রতিটি তারিখ আপনার দেওয়া **শুরুর তারিখ** থেকে পরিকল্পিত হয় - ফাঁকা রাখলে আজ - এবং আপনি একটি না দিলে লক্ষ্য শেষ তারিখ সেটি অনুসরণ করে। কাজগুলো সাধারণ কাজ, কাউকে বরাদ্দ করা নেই, এবং কিছুতেই টিক দেওয়া নেই। নাম ধরে স্ট্যাটাস বা অবস্থান দরকার এমন একটি অ্যাসেট টার্গেট (যেমন "Retired") শুধু তখনই যোগ হয় যখন সেই নাম আপনার ইনস্টলে আছে।',
            'p3' => 'নিজের টেমপ্লেট বানাতে, ভালোভাবে সম্পন্ন হওয়া একটি প্রজেক্ট খুলে **টেমপ্লেট** চাপুন। কী রাখবেন বেছে নিন: ধাপ ও কাজ, পরিধি, ঝুঁকি ও অনুমান, টলারেন্স (অনুমোদিত অতিরিক্ত ব্যয়সহ) এবং অ্যাসেট টার্গেট। টেমপ্লেট বদলাতে, সেটি থেকে একটি প্রজেক্ট শুরু করুন, প্রজেক্ট বদলান, **টেমপ্লেট** চাপুন এবং **আপনার একটি টেমপ্লেট প্রতিস্থাপন করুন** বেছে নিন - বিল্ট-ইনগুলো এভাবে কপি করা যায়, কখনো ওভাররাইট করা যায় না। মানুষ, কোম্পানি, লিঙ্ক ও অগ্রগতি কখনো রাখা হয় না, তাই একটি টেমপ্লেট যেকোনো কোম্পানির জন্য কাজ করে। **প্রজেক্ট - সেটিংস - টেমপ্লেট** সবগুলো তালিকাভুক্ত করে: যে বিল্ট-ইনটি কখনো ব্যবহার করেন না তা লুকান, এবং নিজেরগুলোর নাম বদলান, বন্ধ করুন বা মুছুন। টেমপ্লেট সংরক্ষণ ও দেখভালে টেমপ্লেট অনুমতি লাগে; প্রজেক্ট তৈরি করতে পারেন এমন যে কেউ একটি থেকে শুরু করতে পারেন।',
            'p4' => '৩.৩.০ থেকে একটি টেমপ্লেট পরিকল্পনার **নির্ভরতা**, প্রতিটি ধাপের **গেট চেকলিস্ট** (এবং এটি গো-লাইভ গেট কিনা - এখনো সাইন-অফের জন্য কারও নাম ছাড়া) এবং, আপনি রাখলে, লক্ষ্যমাত্রাসহ **সুবিধাগুলোও** বহন করে (বেসলাইন কখনো নয় - সেগুলো নতুন প্রজেক্টে মাপা হয়)। পাঁচটি বিল্ট-ইন টেমপ্লেটে তিনটিই আসে।',
        ],
        'targets' => [
            'nav' => 'অ্যাসেট টার্গেট',
            'title' => 'অ্যাসেট টার্গেট: সরাসরি অ্যাসেট থেকে অগ্রগতি',
            'intro' => '"৪৮০টি ল্যাপটপের মধ্যে ৩১২টি প্রতিস্থাপিত", অ্যাসেট থেকেই গোনা।',
            'p1' => 'একটি অ্যাসেট টার্গেট প্রজেক্টের সংক্ষিপ্ত বিবরণে থাকে এবং অ্যাসেটে কিছু গণনা করে: যে Latitude 5430গুলো অবসরে গেছে, যে Windows মেশিনগুলো এখন Windows 11-এ, যে ল্যাপটপে BitLocker চালু। পেজ খোলার প্রতিবার গণনা করা হয়, তাই কেউ অ্যাসেট বদলানো মাত্র প্রজেক্ট এগিয়ে যায় - কাউকে কিছু টিক দিতে মনে রাখতে হয় না। প্রতিটি টার্গেট তার অগ্রগতির একটি রেখা আঁকে, সেট করার দিন থেকে প্রতিদিন একটি বিন্দু।',
            'p2' => '**কোন অ্যাসেট** বেছে নিন: হয় যেগুলো একটি ধরন এবং/অথবা কিছু টেক্সট ধারণকারী ফিল্ডের সাথে **মেলে** (মডেলে 5430 আছে), অথবা সংযোগ ট্যাবে **এই প্রজেক্টের সাথে যুক্ত** যেগুলো। তারপর বেছে নিন **কখন একটি সম্পন্ন গণ্য হবে**: একটি স্ট্যাটাস, একটি অবস্থান, অপারেটিং সিস্টেম, ফিচার রিলিজ, মডেল, প্রস্তুতকারক, BitLocker বা TPM সংস্করণ। আপনি টাইপ করার সময় ডায়ালগ দেখায় কতগুলো অ্যাসেট মেলে এবং কতগুলো সম্পন্ন। একটি টার্গেট শুধু প্রজেক্টের নিজের কোম্পানির অ্যাসেট গোনে।',
            'p3' => 'প্রতিটি টার্গেটের একটি তারিখ থাকে - নিজের, অথবা প্রজেক্টের লক্ষ্য শেষ তারিখ। তারিখ পেরিয়ে গিয়েও শেষ না হওয়া টার্গেট প্রজেক্টকে লাল করে; যেটি সেট করার দিন থেকে তারিখ পর্যন্ত সরলরেখার চেয়ে ২৫ পয়েন্টের বেশি পিছিয়ে, সেটি হলুদ করে। **এখনো করার বাকি** বাকি অ্যাসেটগুলো তালিকাভুক্ত করে, প্রতিটি অ্যাসেটের একটি লিঙ্ক। টার্গেট সেট করতে এবং কোন অ্যাসেট পিছিয়ে তা দেখতে প্রজেক্ট পরিবর্তনের অনুমতির পাশাপাশি অ্যাসেটে অ্যাক্সেস লাগে; নিয়ম বদলালে এর রেখা আবার গোড়া থেকে শুরু হয়।',
        ],
        'health' => [
            'nav' => 'হেলথ',
            'title' => 'হেলথ কীভাবে হিসাব করা হয়',
            'intro' => 'পরিকল্পনা থেকে, কারও মেজাজ থেকে নয়।',
            'p1' => 'কেউ হাতে ঠিক না করলে, একটি চলমান প্রজেক্টের হেলথ দেখানোর প্রতিবার এর কাজ ও লক্ষ্য তারিখ থেকে হিসাব করা হয়। নিচের সংখ্যাগুলো ডিফল্ট; **প্রজেক্ট - সেটিংস - হেলথ**-এ এগুলো বদলানো যায়।',
            'green_d' => 'নিচের কোনোটিই প্রযোজ্য নয়।',
            'amber_d' => 'অন্তত একটি খোলা কাজ বিলম্বিত, একটি মাইলস্টোন মিস হয়েছে অথবা একটি নির্ভরতা বা সিদ্ধান্ত তারিখ পেরিয়েছে (এ দুটির প্রতিটি প্রজেক্ট - সেটিংস - হেলথ-এ লাল বা কিছুই নয় করা যায়), লক্ষ্য তারিখ কাছে এবং কাজের খুব কম সম্পন্ন - ডিফল্টে ১৪ দিনের মধ্যে তিন-চতুর্থাংশের কম সম্পন্ন - অথবা যুক্ত টিকিটে হঠাৎ বৃদ্ধি: ডিফল্টে গত ৭ দিনে ৫ বা তার বেশি, যা গো-লাইভের পর সাধারণত মানে কিছু ঠিক করা দরকার।',
            'red_d' => 'খোলা কাজ রেখে লক্ষ্য তারিখ পেরিয়ে গেছে, খোলা কাজের অনেক বেশি অংশ বিলম্বিত - ডিফল্টে এক-চতুর্থাংশ বা তার বেশি - অথবা প্রজেক্ট একটি টলারেন্স পেরিয়ে গেছে (গেট দেখুন)। অ্যাসেট টার্গেটও গণ্য হয়: তারিখ পেরোনো একটি প্রজেক্টকে লাল করে, অনেক পিছিয়ে থাকা একটি সবুজ প্রজেক্টকে হলুদ করে (অ্যাসেট টার্গেট দেখুন)।',
            'p2' => 'নিজে ঠিক করতে, প্রজেক্ট সম্পাদনা করে একটি হেলথ বেছে নিন; কেন তা বলে একটি লাইন যোগ করুন। এটি আবার ফিরিয়ে দিতে **আমার জন্য হিসাব করুন** বেছে নিন। বন্ধ ও বাতিল প্রজেক্টের কোনো হেলথ নেই।',
