            'intro' => 'প্রতি ব্যক্তির জন্য একটি কাজের তালিকা, দুটি নয়।',
            'p1' => 'প্রজেক্টে যোগ করা একটি কাজ একটি সাধারণ কাজ: এটি কাজ বোর্ডে দেখা যায়, বরাদ্দ, নির্ধারণ, সময় রেকর্ড, মন্তব্য করা এবং উপকাজ ও চেকলিস্ট দেওয়া যায়, এবং স্বাভাবিক ইমেল ও নোটিফিকেশন পাঠায়। অগ্রগতি শীর্ষস্তরের কাজ গোনে; উপকাজ তার কাজের অন্তর্ভুক্ত।',
            'p2' => 'প্রজেক্ট মুছলে এর কাজ কখনো মুছে যায় না। সেগুলো কাজ বোর্ডে থেকে যায় এবং শুধু প্রজেক্টের অন্তর্ভুক্ত থাকে না। ফেজ সরানোও একইভাবে কাজ করে: এর কাজগুলো প্রজেক্টেই থাকে, শুধু কোনো ফেজে নয়।',
