        'contractors' => [
            'nav' => 'ঠিকাদার',
            'title' => 'ঠিকাদারদের করা কাজ',
            'intro' => 'যখন বাইরের কোনো প্রতিষ্ঠান প্রজেক্টের একটি অংশ করে - ক্যাবলিং, স্থানান্তর, ইনস্টল।',
            'p1' => 'একটি কাজ একজন **ঠিকাদারকে** দেওয়া যায়: চুক্তি থেকে একটি সরবরাহকারী, এবং চাইলে সেখানকার একজন ব্যক্তি। কাজ বোর্ডের কাজ উইন্ডোতে **ঠিকাদার** ও **সেখানকার যোগাযোগ**-এর অধীনে তাদের বেছে নিন। **নিযুক্ত** ব্যক্তি এখানকার সেই ব্যক্তিই থাকেন যিনি কাজের মালিক এবং প্রতিষ্ঠানের পিছনে লেগে থাকেন - তাই ঠিকাদারের কাজে দুজনই থাকে। সরবরাহকারী বেছে নিতে চুক্তিতে অ্যাক্সেস লাগে; কাজ দেখতে পান এমন যে কেউ দেখেন এটি কার কাছে।',
            'p2' => 'ঠিকাদারের কাজ প্ল্যান, টাইমলাইন এবং কাজ বোর্ডে প্রতিষ্ঠানের নাম বহন করে, যেখানে একটি **ঠিকাদার** ফিল্টার একটি প্রতিষ্ঠানের কাজ, সব ঠিকাদারের কাজ, বা একটিও নয় দেখায়। **মানুষ** ট্যাবে, **কাউকে যোগ করুন - ঠিকাদার** একটি প্রতিষ্ঠান, বা সেখানকার একজনকে, একটি ভূমিকাসহ প্রজেক্টে রাখে, যাতে তারা RACI ম্যাট্রিক্স ও স্টেকহোল্ডার ম্যাপে থাকতে পারে। মানুষের মধ্যে সরবরাহকারীর পেজ তাদের সাথে থাকা প্রতিটি কাজ তালিকাভুক্ত করে।',
            'p3' => 'ঠিকাদারের কাজ **ক্যাপাসিটি**-তে কারও লোডে নেই - এটি নিচে তালিকাভুক্ত, প্রতিটি প্রতিষ্ঠানের জন্য এক লাইন, এর খোলা কাজ, বাকি ঘণ্টা এবং কতগুলো দেরিতে তাসহ। বিলম্বিত-কাজের ডাইজেস্ট, AI ব্রিফিং এবং **AI-কে জিজ্ঞাসা** সবই বলে কোন দেরির কাজ ঠিকাদারের কাছে, এবং AI-কে জিজ্ঞাসা একটি কাজ ঠিকাদারকে দেওয়ার পরামর্শ দিতে পারে।',
            'p4' => '**ঠিকাদারকে ইমেল** (প্রজেক্ট - সেটিংস - সাধারণ) শুরুতে বন্ধ: ঠিকাদারের কাজ এখানে ট্র্যাক করা হয় এবং আপনি নিজে তাগাদা দেন। এটি চালু করলে প্রতিষ্ঠানের ব্যক্তিকে ইমেল করা হয় যখন তাকে কাজ দেওয়া হয়, শেষ তারিখের দুই দিন আগে, এবং মিস হলে একবার - আপনার আউটগোয়িং মেইলবক্স থেকে, কাজ, তারিখ এবং এখানে কাকে উত্তর দিতে হবে সহ। শুধু ইমেল ঠিকানা আছে এমন ব্যক্তির কাজই পাঠানো হয়; প্রতিটি ইমেল পাঠানোর লগে **ঠিকাদারের জন্য কাজ** হিসেবে থাকে।',
