            'p1' => 'সংযোগ ট্যাব একটি প্রজেক্টকে সে যে রেকর্ডগুলো ছোঁয় সেগুলোর সাথে যুক্ত করে: প্রতিস্থাপিত ল্যাপটপ, সে যে পরিবর্তনগুলো তোলে (অনুমোদিত কিনা সহ), যে টিকিটগুলো সে ঘটিয়েছে, যে সরবরাহকারী চুক্তির উপর নির্ভর করে, CMDB-র সিস্টেম, নলেজের রানবুক এবং যে সমস্যাগুলো ঠিক করতে তার অস্তিত্ব। অনুসন্ধান করতে একটি ধরনের নিচের বক্সে টাইপ করুন, এবং যুক্ত করতে একটি ফলাফল বেছে নিন। সংক্ষিপ্ত বিবরণ দেখায় প্রতিটির কতগুলো যুক্ত।',
            'p2' => 'আপনি একটি ধরন দেখেন শুধু যদি আপনি তার মডিউল খুলতে পারেন, এবং একটি লিঙ্ক শুধু যদি অপর প্রান্তের রেকর্ড খুলতে পারেন। একাধিক কোম্পানির ইনস্টলে, যন্ত্রপাতি, পরিবর্তন, টিকিট, সমস্যা ও কনফিগারেশন আইটেম প্রজেক্টের নিজের কোম্পানির হতে হবে। লিঙ্ক খুললে রেকর্ড নিজে কখনো বদলায় না, এবং দুটোই প্রজেক্টের ইতিহাসে লেখা হয়।',
