            'p1' => 'প্রস্তাবিত বা সক্রিয় প্রতিটি প্রজেক্ট তার লক্ষ্য শেষ তারিখ শেয়ার্ড ক্যালেন্ডারে "Project due" হিসেবে রাখে, এবং বন্ধ হয়নি এমন প্রতিটি ধাপ, ফেজ বা স্প্রিন্টও তার শেষ তারিখ সেখানে রাখে, প্রতিটি মাইলস্টোনও তা পৌঁছানো পর্যন্ত। এগুলো Projects নামের একটি বিভাগে সারাদিনের এন্ট্রি, যার নাম বা রঙ আপনি ক্যালেন্ডারে বদলাতে পারেন। প্রজেক্টে একটি তারিখ বদলান, ক্যালেন্ডার তা অনুসরণ করে; একটি ধাপ বন্ধ করুন, বা প্রজেক্টটি স্থগিত, বন্ধ বা বাতিল করুন, এর এন্ট্রিগুলো চলে যায়। **প্রজেক্ট - সেটিংস - সাধারণ** বেছে নেয় ক্যালেন্ডার সবগুলো, শুধু লক্ষ্য শেষ তারিখ, নাকি কিছুই দেখাবে না।',
            'p2' => 'এন্ট্রিগুলো প্রজেক্ট লেখে, তাই ক্যালেন্ডারে একটিতে করা পরিবর্তন পরের বার কোনো প্রজেক্ট বদলালে প্রতিস্থাপিত হয়। এদের ভাষা ইংরেজি, অন্য স্বয়ংক্রিয় এন্ট্রিগুলোর মতোই। ক্যালেন্ডার এন্ট্রির কোনো কোম্পানি নেই, তাই একাধিক কোম্পানির ইনস্টলে ক্যালেন্ডার খুলতে পারেন এমন সবাই প্রতিটি প্রজেক্টের তারিখ দেখেন।',
