            'title' => 'অ্যালার্ট, এবং ওয়ার্কফ্লোতে প্রজেক্ট',
            'intro' => 'কিছু দরকার হলে প্রজেক্ট ম্যানেজার জানতে পারেন, এবং ওয়ার্কফ্লো তাতে কাজ করতে পারে।',
            'p1' => 'নোটিফিকেশন বেল একটি প্রজেক্টের ম্যানেজারকে জানায় যখন এর হেলথ বদলায় (সবুজ, হলুদ বা লাল, হিসাব করা বা হাতে ঠিক করা), যখন এটি সময় বা ঝুঁকির টলারেন্স ছাড়িয়ে যায়, যখন একটি ধাপ, ফেজ বা স্প্রিন্ট ৭ দিনে এবং আবার আগের দিন শেষ হয়, যখন একটি মাইলস্টোন ৭ দিন দূরে, আগের দিন, এবং মিস হলে, এবং যখন কেউ পরিবর্তনের অনুরোধ তোলে, অনুমোদন বা প্রত্যাখ্যান করে। প্রতিটি ঘটার সময় একবারই বলা হয়: যে প্রজেক্ট লাল থেকে যায় সেটি প্রতি ঘণ্টায় বাজে না, এবং যে লঙ্ঘন মুছে গিয়ে ফিরে আসে সেটি নতুন খবর। নিজের করা পরিবর্তন সম্পর্কে কাউকে জানানো হয় না। প্রত্যেকে এগুলো বন্ধ করতে পারেন, অথবা ধাপ বন্ধ হলে বা মাইলস্টোন পৌঁছালে বেল চালু করতে পারেন, **পছন্দ - নোটিফিকেশন**-এ।',
            'p2' => 'একই মুহূর্তগুলো **ওয়ার্কফ্লো**-তে ট্রিগার: একটি প্রজেক্টের হেলথ বদলায়, একটি টলারেন্স লঙ্ঘিত হয়, একটি ধাপ বন্ধ হয়, একটি ধাপ শীঘ্রই শেষ হয়, একটি মাইলস্টোন আসছে, মিস হয়েছে বা পৌঁছেছে, একটি পরিবর্তনের অনুরোধ তোলা বা সিদ্ধান্ত হয়, এবং একটি প্রজেক্ট তৈরি, হালনাগাদ বা মোছা হয়। একটি ওয়ার্কফ্লো প্রজেক্ট লাল হলে Teams বা Slack-এ পোস্ট করতে, টলারেন্স লঙ্ঘিত হলে টিকিট তুলতে, বা ধাপ বন্ধ হলে বোর্ডকে ইমেল করতে পারে, প্রজেক্টের নাম, কোড, হেলথ, ম্যানেজার ও তারিখ ব্যবহার করে।',
            'p3' => 'হেলথ ও টলারেন্স পরিকল্পনা থেকে হিসাব করা হয়, তাই কাউকে দেখতে হয়। প্রজেক্টে কিছু সংরক্ষণ করলে তখনই দেখা হয়; নইলে নির্ধারিত ওয়ার্কফ্লো জব এটি করে (cron/workflow_scheduled.php, ঘণ্টায় একবারই যথেষ্ট), এবং কোনো নির্ধারিত জব নেই এমন ইনস্টলে পোর্টফোলিও খুললে সর্বোচ্চ প্রতি ১৫ মিনিটে দেখা হয়। রাতারাতি বিলম্বিত হওয়া একটি কাজ যেটি আগে আসে সেটিই ধরে।',
            'p4' => '**অনুস্মারক।** প্রতিটি প্রজেক্ট ম্যানেজার তাঁর সক্রিয় প্রজেক্টের **বিলম্বিত কাজের** তালিকা সহ একটি বেল পান - সোমবারে সাপ্তাহিক, প্রতিদিন বা কখনো নয় (প্রজেক্ট -> সেটিংস -> সাধারণ, *বিলম্বিত কাজের ডাইজেস্ট*)। আর যখন একটি প্রস্তাব, পরিবর্তনের অনুরোধ, গেট সাইন-অফ বা রিপোর্ট খসড়া সিদ্ধান্তের জন্য **৩ দিন** অপেক্ষা করেছে, যাঁরা সিদ্ধান্ত দেন তাঁদের তাগাদা দেওয়া হয় - *এখনো আপনার সাইন-অফের অপেক্ষায়* - এবং প্রতি ৩ দিনে আবার (*তাগাদা দিন*; ০ = কোনো অনুস্মারক নয়)। ৪৫ দিনের চেয়ে পুরোনো কিছুতে তাগাদা দেওয়া হয় না।',
            'p5' => 'বেল আরও জানায়: কেউ একটি RAID এন্ট্রি এসক্যালেট করলে প্রজেক্ট ম্যানেজারকে; নতুন প্রস্তাব সম্পর্কে অনুমোদনকারীদের, এবং সিদ্ধান্ত সম্পর্কে প্রস্তাবকারীকে; গেটে সাইন-অফ দরকার হলে একজন নামকরা ব্যক্তিকে; পর্যালোচনা বাকি হলে, বন্ধ হওয়ার পরও, একটি সুবিধার মালিক ও প্রজেক্ট ম্যানেজারকে; এবং নির্ধারিত রিপোর্ট খসড়া হলে প্রজেক্ট ম্যানেজারকে। এগুলোর প্রতিটি, বিলম্বিত ডাইজেস্ট ও তাগাদা **ওয়ার্কফ্লো**-তেও ট্রিগার।',
        ],
        'budget' => [
            'nav' => 'বাজেট',
            'title' => 'বাজেট: পরিকল্পিত বনাম প্রকৃত',
            'intro' => 'প্রজেক্টের খরচ কত হওয়ার কথা ছিল, কত হয়েছে, এবং দুটির ব্যবধান কতটা।',
            'p1' => 'বাজেট ট্যাবে (স্টেজড প্রজেক্টে চালু থাকে; অন্যগুলোর জন্য টুলস থেকে চালু করুন) পরিকল্পিত বাজেট, প্রকৃত ব্যয়, কত বাকি আছে এবং কতটা ব্যবহৃত হয়েছে তা দেখা যায়। যে খাতে খরচ হবে বলে আশা করেন - হার্ডওয়্যার, লাইসেন্স, সরবরাহকারী - প্রতিটির জন্য একটি **বাজেট লাইন** যোগ করুন, সঙ্গে কত পরিকল্পিত ছিল আর কত খরচ হয়েছে। একটি লাইন সংযোগ ট্যাবে যুক্ত করা কোনো চুক্তির নাম নিতে পারে: তার প্রকৃত ঘর খালি রাখলে চুক্তির মূল্য ব্যবহৃত হয়। এতে প্রজেক্টের কোম্পানির একটি কস্ট সেন্টারও থাকতে পারে।',
            'p2' => '**শ্রম** হলো প্রজেক্টের কাজগুলোতে লগ করা সময়। প্রজেক্ট - সেটিংস - বাজেট ঠিক করে এটি ঘণ্টায় দেখানো হবে, একটি ঘণ্টাপ্রতি হারে মূল্য ধরা হবে (যা কোনো প্রজেক্ট বদলাতে পারে), নাকি প্রতিটি বিশ্লেষকের নিজস্ব হারে। প্রতিটি হার একটি তারিখ থেকে কার্যকর হয়, তাই নতুন হার আগে লগ করা সময়ের মূল্য বদলায় না, আর সেটিং বদলালে কিছুই নতুন করে লেখা হয় না - সময় সময় হিসেবেই সংরক্ষিত থাকে।',
            'p4' => '**টাকা কোথায় যায়** প্রতিটি বিভাগের জন্য পরিকল্পিত বনাম প্রকৃত চার্টে দেখায়, শ্রমের মূল্য ধরা হলে তা-সহ। **টেবিল** একই সংখ্যা টেবিলে দেখায়।',
            'p5' => 'একটি লাইন **কখন** তাও বলতে পারে: টাকা কোন তারিখে বেরোনোর কথা এবং কোন তারিখে বেরিয়েছে। **সময়ের সাথে ব্যয়** সেগুলো দিনে দিনে যোগ করে - পরিকল্পিত এবং এ পর্যন্ত খরচ - আজ থেকে লক্ষ্য শেষ তারিখ পর্যন্ত একটি ড্যাশ-রেখার **পূর্বাভাস** সহ, আর মাপার জন্য বাজেট, সর্বশেষ বেসলাইনের বাজেট এবং অতিরিক্ত ব্যয়ের সহনসীমা রেখা হিসেবে থাকে। **পূর্বাভাস** হলো প্রজেক্টের এখন যা খরচ হবে বলে ধরা হচ্ছে: প্রতিটি লাইনের নিজস্ব পূর্বাভাস (একটি লিখুন, নইলে পরিকল্পিত ও খরচের মধ্যে বড়টি), সঙ্গে শ্রম - লগ করা, এবং খোলা কাজের এস্টিমেটে যা বাকি, আজকের হারে মূল্য ধরে। প্রকৃত ছাড়া একটি শ্রম লাইন হলো শ্রমের পরিকল্পনা, তাই শ্রম কখনো দুবার গোনা হয় না। প্রজেক্ট - সেটিংস - বাজেট ঠিক করে এস্টিমেট গণ্য হবে কিনা, এবং **অতিরিক্ত ব্যয়ের অনুমতি** খরচ হওয়া অর্থ মাপবে নাকি পূর্বাভাস - যা আগে সতর্ক করে।',
            'p3' => 'প্রতিটি প্রজেক্ট যে **মুদ্রায়** তৈরি হয়েছিল সেটিই রাখে, এবং ভিন্ন মুদ্রার অঙ্ক কখনো একসাথে যোগ করা হয় না: অন্য মুদ্রার একটি চুক্তি তার লাইনে দেখানো হয় কিন্তু গোনা হয় না। প্রজেক্ট - সেটিংস প্রজেক্টকে বেছে নিতে দিলে মুদ্রা বোতাম প্রজেক্টের লেবেল বদলায় - রূপান্তর করে না। গেট ট্যাবে **অতিরিক্ত ব্যয়ের অনুমতি** একটি খরচের সহনসীমা ঠিক করে: বাজেটের চেয়ে এর বেশি এগিয়ে গেলে প্রজেক্টটি ব্যতিক্রম হয়ে যায়, এবং অফ ট্র্যাক হয়।',
            'p6' => '**আর্নড ভ্যালু** তিনটি রেখা তুলনা করে: প্ল্যানড ভ্যালু (লাইনগুলোর পরিকল্পিত তারিখ অনুযায়ী যেভাবে বাজেট খরচ হওয়ার কথা), আর্নড ভ্যালু (বাজেট গুণ সম্পন্ন কাজের অনুপাত - এস্টিমেট করা ঘণ্টা দিয়ে, এস্টিমেট না থাকলে কাজের সংখ্যা দিয়ে) এবং প্রকৃত খরচ। **CPI** হলো আর্নড ভ্যালু ভাগ প্রকৃত খরচ - ১-এর নিচে হলে সম্পন্ন কাজে যা হওয়ার কথা তার চেয়ে বেশি খরচ হয়েছে; **SPI** হলো আর্নড ভ্যালু ভাগ প্ল্যানড ভ্যালু - ১-এর নিচে হলে পরিকল্পনার পিছনে; **এস্টিমেট অ্যাট কমপ্লিশন** হলো বাজেট ভাগ CPI।',
        ],
        'benefits' => [
            'nav' => 'সুবিধা',
            'title' => 'সুবিধা: প্রজেক্টটি কি কাজে লেগেছে?',
            'intro' => 'প্রজেক্ট কী উন্নত করবে, শুরুর অবস্থা থেকে মাপা - এবং বন্ধ হওয়ার পরে পর্যালোচনা, কারণ বেশিরভাগ সুবিধা তখনই আসে।',
            'p1' => '**সুবিধা** ট্যাবে (স্টেজড প্রজেক্টে চালু থাকে; অন্যগুলোর জন্য টুলস থেকে চালু করুন) প্রজেক্টের যা উন্নত করার কথা তার তালিকা থাকে। একটি **যোগ** করুন: কী উন্নত হবে, কীভাবে এবং কোন এককে মাপা হবে, কোন দিকটি ভালো (বেশি নাকি কম), **বেসলাইন** (আজ কোথায় আছে), **লক্ষ্য** এবং কোন তারিখের মধ্যে পৌঁছাতে হবে, একজন মালিক, এবং কখন পর্যালোচনা হবে। প্রতিটি সুবিধায় বেসলাইন, এখন ও লক্ষ্য পাশাপাশি দেখা যায়, কতটা এগিয়েছে তা-সহ, আর এর একটি অবস্থা: এখনো মাপা হয়নি, চলমান, অর্জিত, অথবা লক্ষ্য তারিখ পেরিয়ে গেছে।',
            'p2' => '**রেকর্ড** একটি পরিমাপ যোগ করে - একটি মান এবং যে তারিখে মাপা হয়েছে। সর্বশেষটিই "এখন"। পর্যালোচনার তারিখে বা তার কাছাকাছি (সর্বোচ্চ ১৪ দিন আগে) রেকর্ড করলে সেটি পর্যালোচনা হিসেবে গণ্য হয়, এবং পরবর্তী পর্যালোচনা সুবিধার ব্যবধান অনুযায়ী এগিয়ে যায়; ব্যবধান ০ হলে একবারই পর্যালোচনা হয়। **ইতিহাস** প্রতিটি পরিমাপের তালিকা দেখায়। কোনো সুবিধা আর নজরে রাখার দরকার না হলে সেটি সম্পাদনা করে **এই সুবিধার পর্যালোচনা বন্ধ করুন** টিক দিন।',
            'p3' => 'পর্যালোচনার তারিখ এলে বেল সুবিধার মালিক ও প্রজেক্ট ম্যানেজারকে জানায় (প্রজেক্ট - সেটিংস - সাধারণ থেকে শুধু মালিককে করা যায়) - **প্রজেক্ট বন্ধ হওয়ার পরেও**; বাতিল প্রজেক্টের পর্যালোচনা হয় না। সংক্ষিপ্ত বিবরণ এবং পোর্টফোলিও কার্ডে বকেয়া পর্যালোচনা দেখানো হয়, আর রিপোর্ট ট্যাবের **ক্লোজার** রিপোর্টে প্রতিটি সুবিধা থাকে: কী অর্জিত হয়েছে এবং কী এখনো বাকি।',
        ],
        'intake' => [
            'nav' => 'প্রস্তাব ও অনুমোদন',
            'title' => 'একটি প্রজেক্টের প্রস্তাব দেওয়া, এবং তা অনুমোদন করা',
            'intro' => 'ফর্মে "আমরা কি পেতে পারি..." থেকে একটি অনুমোদিত প্রজেক্ট পর্যন্ত, তার পক্ষে যুক্তি লিখিতভাবে সহ।',
            'p1' => 'যেকোনো ফর্ম একটি প্রজেক্টের প্রস্তাব দিতে পারে। **ফর্ম**-এ ফর্মটি খুলুন, **এরপর কী ঘটবে**-তে যান এবং "জমা দেওয়ার সময়" এর অধীনে (অথবা যে ফর্ম আগে অনুমোদিত হয় তার জন্য "অনুমোদনের সময়") **প্রজেক্ট প্রস্তাব তৈরি করুন** যোগ করুন। ঘরগুলো খালি রাখলে প্রজেক্টের নাম হয় ফর্মের নাম ও প্রেরকের নামে, সারসংক্ষেপ হয় তাদের উত্তর এবং এটি তাদের কোম্পানির অন্তর্ভুক্ত হয়; অথবা সেগুলো পূরণ করুন - নাম, কেন দরকার, আনুমানিক খরচ, প্রত্যাশিত সুবিধা, কবে লাগবে, কীভাবে চালানো হবে, অগ্রাধিকার, প্রজেক্ট ম্যানেজার - উত্তরগুলো ব্যবহার করে, যেমন {{submission.fields.Budget}}। একই অ্যাকশন **ওয়ার্কফ্লো**-র যেকোনো নিয়মে কাজ করে।',
            'p2' => 'একটি প্রস্তাবের সংক্ষিপ্ত বিবরণে একটি **প্রস্তাব** প্যানেল দেখা যায় - কে প্রস্তাব দিয়েছে এবং কোন ফর্মে, আনুমানিক খরচ, প্রত্যাশিত সুবিধা ও কেন দরকার - এবং পোর্টফোলিওতে একটি **অনুমোদনের অপেক্ষায়** চিপ ও ভিউ থাকে। অনুমোদন না হওয়া পর্যন্ত এটি প্রস্তাবিত থাকতে পারে বা বাতিল করা যায়, আর কিছু নয়। একজন অনুমোদনকারী **অনুমোদন** চাপেন (এটি প্রস্তাবিত থেকে যায় যাতে প্রজেক্ট ম্যানেজার শুরু করেন, অথবা সরাসরি শুরু হয় - এটি একটি সেটিং) অথবা কারণসহ **প্রত্যাখ্যান** চাপেন (এটি বাতিল হয়; কিছু মোছা হয় না)। অনুমোদনকারীরা নতুন প্রস্তাবের কথা বেলে জানতে পান; যিনি প্রস্তাব দিয়েছেন তিনি সিদ্ধান্ত জানতে পান, এবং "একটি প্রজেক্ট প্রস্তাব অনুমোদিত বা প্রত্যাখ্যাত হয়েছে" এর ওপর একটি ওয়ার্কফ্লো ফর্মে যিনি অনুরোধ করেছিলেন তাঁকে ইমেল করতে পারে।',
            'p3' => 'প্রজেক্ট - সেটিংস - সাধারণ ঠিক করে কোন নতুন প্রজেক্টে অনুমোদন লাগবে (ফর্মে প্রস্তাবিতগুলো - ডিফল্ট -, প্রতিটি নতুন প্রজেক্ট, বা কোনোটিই নয়), কে অনুমোদন করবেন (যাঁরা প্রজেক্ট পরিচালনা করেন, বা একজন নির্দিষ্ট ব্যক্তি - প্রজেক্ট ব্যবস্থাপনার অনুমতি থাকলেও সবসময় সিদ্ধান্ত নিতে পারেন) এবং অনুমোদনে কী ঘটবে। সেটিংটি চালু করার আগে তৈরি প্রজেক্টগুলো কখনো প্রভাবিত হয় না।',
        ],
        'control' => [
            'nav' => 'পরিবর্তন নিয়ন্ত্রণ',
            'title' => 'পরিবর্তন নিয়ন্ত্রণ: বেসলাইন এবং পরিবর্তনের অনুরোধ',
            'intro' => 'কী সম্মত হয়েছিল, তারপর থেকে পরিকল্পনা কতটা সরেছে, এবং কে তা সরাতে রাজি হয়েছেন।',
            'p1' => 'একটি **বেসলাইন** পরিকল্পনাটি যেভাবে সম্মত হয়েছিল সেভাবে রেকর্ড করে: শুরু ও লক্ষ্য শেষ তারিখ, পরিকল্পিত বাজেট, কাজ ও আনুমানিক ঘণ্টা, Must আইটেমগুলো, এবং প্রতিটি ধাপ, মাইলস্টোন ও বাজেট লাইন। পরিবর্তন নিয়ন্ত্রণ ট্যাব (স্টেজড প্রজেক্টে চালু থাকে; অন্যগুলোর জন্য টুলস থেকে চালু করুন) এটিকে পরিকল্পনার বর্তমান অবস্থার সাথে তুলনা করে - শেষ তারিখে **+১৭ দিন**, বাজেটে **+£৪,৯৫০ (+২০%)** - এবং আইটেম ধরে ধরে কী সরেছে তা তালিকাভুক্ত করে: দুই সপ্তাহ পিছিয়ে যাওয়া একটি মাইলস্টোন, বেড়ে যাওয়া একটি বাজেট লাইন, যোগ হওয়া একটি Must আইটেম। অন্য কোনো বেসলাইনের সাথে মাপতে **তুলনা করুন** এর অধীনে একটি পুরোনো বেসলাইন বাছুন। হাতে একটি নিতে **বেসলাইন** চাপুন, চাইলে একটি লেবেলসহ; বেসলাইন কখনো সম্পাদনা করা হয় না, বরং নতুন একটি নেওয়া হয়।',
            'p2' => 'একটি **পরিবর্তনের অনুরোধ** সম্মত পরিকল্পনা সরানোর আগেই তা সরানোর অনুমতি চায়: পরিবর্তনটি কী, কেন, এবং সময় (দিন, + মানে দেরি), খরচ (+ বেশি, - সাশ্রয়) ও পরিধির ওপর এর প্রভাব কী। **উত্থাপন** চাপুন। অপেক্ষা করার সময় যিনি তুলেছেন তিনি এটি সম্পাদনা বা প্রত্যাহার করতে পারেন। এটি **অনুমোদিত** হলে একটি নতুন বেসলাইন নেওয়া হয় - পরিবর্তিত পরিকল্পনাটিই সম্মত পরিকল্পনা হয়ে যায় - এবং ডিফল্টভাবে লক্ষ্য শেষ তারিখ এর দিন অনুযায়ী সরে যায় আর এর খরচ এর নামে একটি বাজেট লাইন হয়ে যায়। **প্রত্যাখ্যান** সিদ্ধান্ত রেকর্ড করে এবং কিছুই বদলায় না। অনুরোধ কখনো মোছা হয় না: সেগুলোই পরিকল্পনা কেন সরেছে তার রেকর্ড, এবং প্রতিটি ইতিহাসে থাকে। অন্য কেউ অনুরোধ তুললে প্রজেক্ট ম্যানেজার তা জানতে পান, আর অপেক্ষমাণ অনুরোধ সংক্ষিপ্ত বিবরণ ও পোর্টফোলিও কার্ডে দেখা যায়।',
            'p3' => 'প্রজেক্ট - সেটিংস - সাধারণ ঠিক করে এটি আপনার জন্য কীভাবে কাজ করবে: প্রজেক্ট সক্রিয় হলে **নিজে থেকে** একটি বেসলাইন নেওয়া হবে কিনা, নাকি তখন **এবং** প্রতিটি ধাপ শুরু হলে (ডিফল্ট), নাকি শুধু হাতে; পরিবর্তনের অনুরোধ **কে সিদ্ধান্ত নেবেন** - প্রজেক্ট ম্যানেজার বা প্রজেক্ট পরিচালনার অনুমতি আছে এমন যে কেউ (ডিফল্ট), প্রজেক্টের দলের যে কেউ, বা শুধু প্রজেক্ট পরিচালনার অনুমতি থাকা ব্যক্তিরা; যিনি অনুরোধ তুলেছেন তিনিও **সিদ্ধান্ত নিতে** পারবেন কিনা; এবং অনুমোদনে **পরিকল্পনাও সরবে** কিনা নাকি শুধু নতুন বেসলাইন নেওয়া হবে।',
        ],
        'announce' => [
            'nav' => 'বিঘ্ন ঘোষণা',
            'title' => 'সার্ভিস স্ট্যাটাসে বিঘ্ন ঘোষণা',
            'intro' => '"স্থানান্তরের দিন: শনিবার ফোন বন্ধ থাকবে" - ঘটার আগেই সবাইকে জানানো।',
            'p1' => 'সংযোগ ট্যাবে সার্ভিস স্ট্যাটাস খুলতে পারেন এমন ব্যক্তিদের জন্য একটি **সার্ভিস স্ট্যাটাস** প্যানেল আছে। **ঘোষণা** চাপুন, একটি শিরোনাম, কখন শুরু ও শেষ হবে, মানুষের কী জানা দরকার এবং প্রভাবিত পরিষেবাগুলো দিন (অন্য প্রভাব না বাছলে রক্ষণাবেক্ষণ)। ডিফল্টভাবে এটি **পরিকল্পিত রক্ষণাবেক্ষণ** হয়ে যায়: সার্ভিস স্ট্যাটাসে তখনই আসন্ন হিসেবে দেখায়, শুরুর সময়ে ওই পরিষেবাগুলোতে একটি ইনসিডেন্ট হয়ে যায়, এবং শেষে সমাধান হয়। শুরুর আগে ক্রস চিহ্ন দিয়ে এটি প্রত্যাহার করুন। প্যানেলে প্রজেক্ট যা যা ঘোষণা করেছে তার তালিকা থাকে, এবং ঘোষণা ও প্রত্যাহার দুটিই প্রজেক্টের ইতিহাসে যায়।',
            'p2' => '**প্রজেক্ট - সেটিংস - সাধারণ - সার্ভিস স্ট্যাটাসে বিঘ্ন ঘোষণা** ঠিক করে ঘোষণা কী করবে: পরিকল্পিত রক্ষণাবেক্ষণ হিসেবে (ডিফল্ট), সরাসরি একটি ইনসিডেন্ট হিসেবে, অথবা একেবারেই নয়। প্রজেক্ট মুছলে সে যা ঘোষণা করেছিল তা সার্ভিস স্ট্যাটাসে থেকে যায়: এটি প্রকৃত পরিষেবায় প্রকৃত কাজ।',
