            'intro' => 'এই সপ্তাহে আপনার কী নজর দরকার তার একটি ব্রিফিং, এবং আপনার যাচাইয়ের জন্য খসড়া করা স্ট্যাটাস রিপোর্ট।',
            'p1' => '**প্রজেক্ট - সেটিংস - AI**-তে একটি AI প্রদানকারী সেট করা হলে প্রজেক্টের সংক্ষিপ্ত বিবরণে একটি **ব্রিফিং** প্যানেল থাকে। **আমাকে ব্রিফ করো** চাপুন এবং AI প্রজেক্টটি পড়ে - তারিখ, স্বাস্থ্য, সহনসীমা, ধাপ, বিলম্বিত ও আসন্ন কাজ, ঝুঁকি ও ইস্যু, বাজেট এবং গত সপ্তাহের পরিবর্তন, আর ৩.৩.০ থেকে অগ্রাধিকার, মাইলস্টোন, এস্টিমেট, সিদ্ধান্ত, পরিবর্তনের অনুরোধ, আর্নড ভ্যালু, সুবিধা, কোন কাজ অন্যের জন্য অপেক্ষা করছে ও ক্রিটিক্যাল পাথ, গেট চেকলিস্টের যে আইটেম এখনো খোলা এবং স্টেকহোল্ডার ম্যাপও - এবং কোন বিষয়ে নজর দরকার তা সবচেয়ে গুরুত্বপূর্ণটি আগে রেখে চার থেকে সাতটি ছোট পয়েন্টে লেখে। সর্বশেষ ব্রিফিং সবার জন্য পেজে থাকে; নতুন একটি সর্বোচ্চ প্রতি ১০ মিনিটে খসড়া হয়, কারণ প্রতিটিই প্রদানকারীর কাছে একটি কল।',
            'p2' => '**রিপোর্ট** ট্যাবে একটি প্রজেক্টের হাইলাইট, এক্সসেপশন, চেকপয়েন্ট এবং ক্লোজার রিপোর্ট থাকে। ধরন ও সময়কাল বেছে AI-কে দিয়ে একটি লেখাতে **খসড়া** চাপুন, অথবা নিজের শুরু করতে **লিখুন** চাপুন। প্রজেক্ট পরিবর্তন করতে পারেন এমন যে কেউ খসড়া তৈরি, সম্পাদনা ও মুছতে পারেন। **অনুমোদন** করতে পারেন প্রজেক্ট ম্যানেজার, প্রজেক্ট যিনি তৈরি করেছেন এবং প্রজেক্ট পরিচালনার অনুমতি থাকা ব্যক্তিরা - অনুমোদিত রিপোর্ট চূড়ান্ত, সম্পাদনা করা যায় না, এবং এটিই বোর্ড পড়ে। প্রতিটি রিপোর্টে দেখা যায় AI এটি খসড়া করেছে কিনা এবং তারপর কোনো ব্যক্তি এটি বদলেছেন কিনা। **কপি** এটি ক্লিপবোর্ডে রাখে, ইমেল বা নথিতে পেস্ট করার জন্য।',
            'p3' => 'AI শুধু তা-ই দেখে যা অনুরোধকারী ব্যক্তি দেখতে পান: যার সেসব মডিউল নেই তার জন্য টিকিট, পরিবর্তন ও সার্ভিস স্ট্যাটাস বাদ যায়। তাকে বলা আছে প্রজেক্টে যা আছে শুধু তা-ই বলতে, এবং কিছু জানা না থাকলে তা জানাতে - তবুও সে ভুল হতে পারে, তাই অনুমোদনের আগে একটি খসড়া পড়ে নিন। এটি আপনি FreeITSM যে ভাষায় ব্যবহার করেন সেই ভাষায় লেখে। প্রজেক্টে মানুষের টাইপ করা লেখা ডেটা হিসেবে পাঠানো হয়, কখনো নির্দেশ হিসেবে নয়।',
            'p4' => '**নিজে থেকে রিপোর্ট খসড়া করুন** (রিপোর্ট ট্যাবে): প্রজেক্ট সক্রিয় থাকা অবস্থায় প্রতি সপ্তাহে, প্রতি দুই সপ্তাহে বা প্রতি মাসে, সময়কালের শুরুতে একটি হাইলাইট, চেকপয়েন্ট বা এক্সসেপশন রিপোর্ট খসড়া হয় - AI সেট করা থাকলে AI দিয়ে, নইলে লেখার জন্য তথ্যগুলো ধরে রেখে - এবং প্রজেক্ট ম্যানেজারকে জানানো হয়। এটি প্রজেক্ট ম্যানেজারের অ্যাক্সেস দিয়ে লেখা হয়, তাই তাতে শুধু তা-ই থাকে যা তিনি দেখতে পান। এটি কখনো নিজে থেকে অনুমোদিত হয় না। একটি অনুমোদিত রিপোর্টে **পাঠান** চাপলে তা আপনার টিক দেওয়া প্রজেক্ট সদস্যদের এবং অন্য যেকোনো ঠিকানায় ইমেল করা হয়, ওপরে একটি ঐচ্ছিক নোটসহ; রিপোর্টে দেখা যায় এটি কাকে এবং কখন গেছে।',
