            'p1' => 'একটি প্রজেক্টে **AI-কে জিজ্ঞাসা** (ওপরে ডানদিকে) সহকারীকে স্লাইড করে আনে। এটি প্রজেক্টটি পড়ে ঠিক আপনি যেভাবে পারতেন - যা আপনি নিজে খুলতে পারতেন না তা নয় - এবং সহজ ভাষায় উত্তর দেয়, আপনি কখনো প্রজেক্ট চালাননি হোক বা PRINCE2 মুখস্থ জানুন। প্রজেক্ট - সেটিংস - AI-তে একটি AI প্রদানকারী সেট করা থাকলেই এটি কাজ করে।',
            'p2' => 'এটি বুঝে নেয় প্রজেক্টটি কতটা সাজানো হয়েছে। যে প্রজেক্টে নাম ছাড়া প্রায় কিছুই নেই সে একজন **কোচ** পায়: এটি কী নিয়ে, সম্পূর্ণ হলে কেমন দেখাবে, মোটামুটি কখন, কারা জড়িত - এবং তারপর একটি প্রস্তাবিত সাজ: লক্ষ্য, তারিখ, চালানোর পদ্ধতি, ধাপ, শুরুর কাজ, মাইলস্টোন ও সম্ভাব্য ঝুঁকি। চলমান প্রজেক্ট **নজর রাখতে** সাহায্য পায়: কী বিলম্বিত, উচ্চ ঝুঁকি, মিস হওয়া মাইলস্টোন, অপেক্ষমাণ পরিবর্তনের অনুরোধ। কথোপকথনের নিচের বোতামগুলো শুরু করার জন্য একটি প্রশ্ন সুপারিশ করে।',
            'p3' => '**এটি কখনো নিজে থেকে প্রজেক্ট বদলায় না।** প্রস্তাবিত পরিবর্তন একটি কার্ড হিসেবে আসে - প্রতিটির জন্য একটি বাক্স, সবকটি টিক দেওয়া - সঙ্গে **প্রয়োগ** ও **বাতিল**। প্রয়োগ টিক দেওয়াগুলো ঠিক সেভাবে করে যেন আপনি স্ক্রিনগুলোতে নিজে করেছেন, আপনার অনুমতি নিয়ে, এবং সেগুলো ইতিহাসে আপনার নামে দেখায়। প্রজেক্ট বদলানোর অনুমতি না থাকলে সে শুধু পরামর্শ দেয়।',
            'p4' => '**এটি মনে রাখে।** একটি প্রজেক্টে আপনার কথোপকথন রাখা হয়, এবং পুরোনো অংশ একটি ছোট স্মৃতিতে গুটিয়ে নেওয়া হয়, তাই যেখানে ছেড়েছিলেন সেখান থেকেই শুরু করতে পারেন; কিছুক্ষণ দূরে থাকার পর এটি শুরুতেই জানায় কী বদলেছে। **রিস্টার্ট** এটি ভুলে যায়। প্রজেক্ট - সেটিংস - সাধারণ - *AI সহকারীর স্মৃতি* একে প্রত্যেকের নিজস্ব না রেখে পুরো প্রজেক্ট দলের ভাগ করা একটি কথোপকথন বানায়।',
