            'p1' => 'একাধিক কোম্পানি থাকা ইনস্টলে একটি প্রজেক্ট সেই কোম্পানির অন্তর্ভুক্ত যেখানে এটি তৈরি হয়েছে (অথবা আপনার বাছাই করা কোম্পানির), এবং এর কাজগুলোও সেখানকারই। আপনি শুধু আপনার দেখতে পাওয়া কোম্পানির প্রজেক্ট দেখেন, এবং সব কোম্পানি ভিউ সেগুলো একসাথে দেখায়। অন্য কোম্পানির একটি কাজ প্রজেক্টে রাখা যায় না।',
