            'p1' => '**প্রজেক্ট - সেটিংস**-এ সাতটি ট্যাব আছে, এবং প্রতিটির নিজস্ব অনুমতি লাগে, যা **সিস্টেম - রোল**-এ দেওয়া হয়; প্রজেক্ট ব্যবস্থাপনা সাতটিই কভার করে। যার কোনোটিই নেই সে এমন একটি পেজ দেখে যাতে লেখা কনফিগার করার কিছু নেই।',
            'general_d' => 'অন্য কিছু না বাছলে নতুন প্রজেক্ট যেভাবে চলে, কে প্রজেক্ট তৈরি করতে পারে, কে একটি পরিবর্তন করতে পারে, কোন তারিখগুলো ক্যালেন্ডারে যায় এবং সার্ভিস স্ট্যাটাসে বিঘ্ন কীভাবে ঘোষণা হয়। এছাড়া অগ্রাধিকারের শব্দ, পোর্টফোলিওর শুরুর ক্রম, বার্ন-আপ কী গোনে, পরিবর্তন নিয়ন্ত্রণ (স্বয়ংক্রিয় বেসলাইন, কে সিদ্ধান্ত নেয়, নিজের অনুরোধে সিদ্ধান্ত, অনুমোদনে কী ঘটে), সংক্ষিপ্ত বিবরণে টুলবক্স (চালু), AI সহকারীর স্মৃতি (প্রত্যেকের নিজস্ব), ঠিকাদারদের ইমেল করা হবে কিনা (বন্ধ), বিলম্বিত কাজের ডাইজেস্ট (সাপ্তাহিক) ও নাজ (৩ দিন পরে), নতুন প্রজেক্ট কে দেখতে পাবে (প্রজেক্টের অ্যাক্সেস থাকা সবাই), একটি খোলা গেট চেকলিস্ট আইটেম গো আটকায় কিনা (আটকায়), সুবিধা কত ঘন ঘন পর্যালোচনা হয় (প্রতি ৩ মাসে) ও কাকে মনে করানো হয়, এবং কোন প্রস্তাবে অনুমোদন লাগে, কে অনুমোদন করে ও অনুমোদনে কী ঘটে।',
            'health_d' => 'চলমান প্রজেক্ট কখন হলুদ বা লাল হয়: লক্ষ্য কত কাছে, তার মধ্যে কতটা শেষ হতে হবে, কতটা বিলম্বিত কাজ একে লাল করে এবং কতগুলো নতুন যুক্ত টিকিট একে হলুদ করে; মিস হওয়া মাইলস্টোন, বা তারিখ পেরোনো নির্ভরতা বা সিদ্ধান্ত কী করে (ডিফল্টভাবে হলুদ); এবং ক্যাপাসিটি পেজের এক সপ্তাহের ঘণ্টা, টানা স্তর, একাধিক প্রজেক্ট, কর্মদিবস এবং রোটা শিফট গণ্য হবে কিনা।',
            'roles_d' => 'প্রজেক্টের মানুষ ট্যাবে যে রোলগুলো দেওয়া হয়। ক্রম বদলাতে টেনে আনুন; কোনো রোল দেওয়া বন্ধ করতে প্রজেক্টে দেওয়া হয় থেকে টিক তুলুন; একটি মুছলে এর ধারকেরা তাদের প্রজেক্টে কোনো রোল ছাড়াই থাকে।',
            'raid_d' => 'সম্ভাবনার স্কেল ও প্রভাবের স্কেলের স্তরগুলোর পাঁচটি শব্দ, সবচেয়ে নিচেরটি আগে।',
            'ai_d' => 'ব্রিফিং ও খসড়া রিপোর্ট যে AI প্রদানকারী, মডেল ও কী ব্যবহার করে। কী-টি আপনার সংস্থার অর্থ খরচ করে, তাই এর নিজস্ব অনুমতি আছে।',
            'budget_d' => 'নতুন প্রজেক্টের মুদ্রা, প্রজেক্ট নিজের মুদ্রা বাছতে পারবে কিনা, লগ করা সময়ের খরচ কীভাবে ধরা হয়, এবং ঘণ্টাপ্রতি হার - ডিফল্ট ও প্রতিটি বিশ্লেষকের - প্রতিটি একটি তারিখ থেকে। এছাড়া অতিরিক্ত ব্যয়ের অনুমতি খরচ হওয়া অর্থ মাপবে (ডিফল্ট) নাকি পূর্বাভাস, এবং খোলা কাজে যে ঘণ্টা এখনো এস্টিমেট করা আছে তা পূর্বাভাসে গণ্য হবে কিনা (হবে)।',
            'templates_d' => 'নতুন প্রজেক্টের জন্য দেওয়া টেমপ্লেট: বিল্ট-ইন একটি লুকান, এবং প্রজেক্ট থেকে সেভ করাগুলোর নাম বদলান, বন্ধ করুন বা মুছুন। একই অনুমতি কাউকে প্রজেক্টকে টেমপ্লেট হিসেবে সেভ করতে দেয়।',
            'p2' => '**কে প্রজেক্ট তৈরি করতে পারে** হলো হয় প্রজেক্ট খুলতে পারে এমন যে কেউ (ডিফল্ট) অথবা শুধু যারা প্রজেক্ট পরিচালনা করেন। **কে প্রজেক্ট বদলাতে পারে** হলো হয় এর দল (ডিফল্ট) অথবা প্রজেক্ট খুলতে পারে এমন যে কেউ। একটি প্রজেক্টের দল হলো এর প্রজেক্ট ম্যানেজার, যিনি এটি তৈরি করেছেন এবং এর সদস্যরা, সদস্য হিসেবে থাকা দলের বিশ্লেষকরা সহ। যাঁরা প্রজেক্ট পরিচালনা করেন এবং অ্যাডমিনিস্ট্রেটররা সবসময় যেকোনো প্রজেক্ট বদলাতে পারেন।',
            'p3' => 'সেটিং যা-ই বলুক, একটি প্রজেক্ট **মোছা** সবসময় এর প্রজেক্ট ম্যানেজার, যিনি এটি তৈরি করেছেন এবং যাঁরা প্রজেক্ট পরিচালনা করেন তাঁদের মধ্যেই সীমাবদ্ধ। কোনো প্রজেক্ট বদলানোর অনুমতি না থাকলে এর পেজ সেই বোতামগুলো লুকিয়ে রাখে, এবং সার্ভারও যেকোনো ভাবে পরিবর্তনটি প্রত্যাখ্যান করে।',
        ],
