            'p1' => 'প্রজেক্ট REST API-র মাধ্যমে পড়া ও বদলানো যায়, এবং MCP সার্ভারের মাধ্যমে একটি AI সহকারী পড়তে পারে। দুটিই **সিস্টেম - API**-তে সেট করা হয়, এবং একটি API key শুধু সেই কোম্পানিগুলোতেই পৌঁছায় যা এর বিশ্লেষক দেখতে পান।',
            'p2' => '**ওয়ার রুম**-এ Warbot প্রজেক্ট নিয়েও প্রশ্নের উত্তর দেয় - "কোন প্রজেক্ট অফ ট্র্যাকে?", "এই সপ্তাহে কোনো প্রজেক্ট বড় কিছু করছে কি?" - অথবা **/projects**, **/project** ও **/dates** ব্যবহার করুন। এটি শুধু প্রজেক্ট খুলতে পারেন এমন ব্যক্তিদের দেওয়া হয়, তাঁরা যে প্রজেক্ট দেখতে পান সেগুলো নিয়েই উত্তর দেয়, এবং কখনো অর্থের কথা বলে না: চ্যানেলের সবাই এর উত্তর পড়েন।',
